INSERT INTO mcp_server_registry (server_code, server_name, description, base_url, transport_type, enabled) VALUES
('local-agent-server', 'Local Agent MCP Server', '??Spring??????MCP??', 'http://localhost:8080/mcp', 'HTTP', true)
INSERT INTO mcp_tool_catalog (server_code, tool_name, title, description, input_schema, output_schema, annotations, tags, enabled, version, requires_approval, sensitivity, raw_payload, embedding) VALUES
('local-agent-server', 'acquire_execution_lock', 'acquire_execution_lock', $json$获取分布式执行锁，避免同一资源被并发重复执行。适用于阶段调度、节点执行、外部资源操作（文件/窗口/任务实例）等不可重入场景。调用方需提供 lockKey 与 owner，系统会尝试以原子方式占锁并返回是否成功、过期时间与占用者信息；当锁已被占用时不会报错中断，而是返回 acquired=false 和 currentOwner，便于上层做重试、排队或降级决策。建议与 release_execution_lock 成对使用，并在 finally/补偿逻辑中释放锁以降低锁泄漏风险。$json$, $json${"type": "object", "properties": {"lockKey": {"type": "string", "description": "锁键（必填）。建议使用具有业务语义且稳定唯一的键，如 plan:{planId}:phase:{phaseId}。"}, "owner": {"type": "string", "description": "锁持有者标识（必填）。建议传执行实例ID/会话ID，释放时必须与此值一致。"}, "ttlSec": {"type": "integer", "description": "锁过期秒数（可选）。用于防止死锁；不传时使用系统默认值。"}}, "required": ["lockKey", "owner"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "acquire_execution_lock", "description": "获取分布式执行锁，避免同一资源被并发重复执行。适用于阶段调度、节点执行、外部资源操作（文件/窗口/任务实例）等不可重入场景。调用方需提供 lockKey 与 owner，系统会尝试以原子方式占锁并返回是否成功、过期时间与占用者信息；当锁已被占用时不会报错中断，而是返回 acquired=false 和 currentOwner，便于上层做重试、排队或降级决策。建议与 release_execution_lock 成对使用，并在 finally/补偿逻辑中释放锁以降低锁泄漏风险。", "version": "1.0.0", "owner": "System", "beanName": "executionLockTools", "methodName": "acquireExecutionLock", "inputSchema": {"type": "object", "properties": {"lockKey": {"type": "string", "description": "锁键（必填）。建议使用具有业务语义且稳定唯一的键，如 plan:{planId}:phase:{phaseId}。"}, "owner": {"type": "string", "description": "锁持有者标识（必填）。建议传执行实例ID/会话ID，释放时必须与此值一致。"}, "ttlSec": {"type": "integer", "description": "锁过期秒数（可选）。用于防止死锁；不传时使用系统默认值。"}}, "required": ["lockKey", "owner"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'append_node_output', 'append_node_output', $json$写入节点执行产物，区分完整输出与下游可消费输出。outputJson 用于保存完整执行结果以便审计与复盘；outputForNext 用于保存精简关键字段供后续节点直接消费。适合在节点成功后调用，也可在失败时写入错误上下文辅助重规划。若输出体较大，建议上层先做裁剪或摘要以降低存储与网络开销。$json$, $json${"type": "object", "properties": {"planId": {"type": "string", "description": "计划ID（必填）。用于定位节点所属计划。"}, "nodeId": {"type": "string", "description": "节点ID（必填）。用于定位写入目标节点。"}, "outputJson": {"type": "string", "description": "完整输出JSON字符串（必填）。建议包含执行结果、日志摘要、关键指标等。"}, "outputForNext": {"type": "string", "description": "下游消费JSON字符串（可选）。建议仅保留后续节点真正需要的字段。"}}, "required": ["planId", "nodeId", "outputJson"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "append_node_output", "description": "写入节点执行产物，区分完整输出与下游可消费输出。outputJson 用于保存完整执行结果以便审计与复盘；outputForNext 用于保存精简关键字段供后续节点直接消费。适合在节点成功后调用，也可在失败时写入错误上下文辅助重规划。若输出体较大，建议上层先做裁剪或摘要以降低存储与网络开销。", "version": "1.0.0", "owner": "System", "beanName": "planNodeTools", "methodName": "appendNodeOutput", "inputSchema": {"type": "object", "properties": {"planId": {"type": "string", "description": "计划ID（必填）。用于定位节点所属计划。"}, "nodeId": {"type": "string", "description": "节点ID（必填）。用于定位写入目标节点。"}, "outputJson": {"type": "string", "description": "完整输出JSON字符串（必填）。建议包含执行结果、日志摘要、关键指标等。"}, "outputForNext": {"type": "string", "description": "下游消费JSON字符串（可选）。建议仅保留后续节点真正需要的字段。"}}, "required": ["planId", "nodeId", "outputJson"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'apply_unified_patch', 'apply_unified_patch', $json$将 unified diff 补丁应用到目标仓库，支持预检模式。适用于自动修复链路中把模型生成 patch 安全落地。checkOnly=true 时仅执行可应用性检查，不实际改写文件；正式模式会执行真实补丁应用。返回包含 exitCode、stdout/stderr 尾部、checkOnlyResult 等信息，便于上层做自动决策、失败回滚与审计记录。$json$, $json${"type": "object", "properties": {"repoPath": {"type": "string", "description": "仓库路径（必填）。补丁将在该目录执行 git apply。"}, "patchText": {"type": "string", "description": "unified diff 文本（必填）。建议包含完整文件头与变更块。"}, "checkOnly": {"type": "boolean", "description": "是否仅检查可应用性（可选）。true=仅检查，false=实际应用。"}}, "required": ["repoPath", "patchText"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "apply_unified_patch", "description": "将 unified diff 补丁应用到目标仓库，支持预检模式。适用于自动修复链路中把模型生成 patch 安全落地。checkOnly=true 时仅执行可应用性检查，不实际改写文件；正式模式会执行真实补丁应用。返回包含 exitCode、stdout/stderr 尾部、checkOnlyResult 等信息，便于上层做自动决策、失败回滚与审计记录。", "version": "1.0.0", "owner": "System", "beanName": "codeOpsTools", "methodName": "applyUnifiedPatch", "inputSchema": {"type": "object", "properties": {"repoPath": {"type": "string", "description": "仓库路径（必填）。补丁将在该目录执行 git apply。"}, "patchText": {"type": "string", "description": "unified diff 文本（必填）。建议包含完整文件头与变更块。"}, "checkOnly": {"type": "boolean", "description": "是否仅检查可应用性（可选）。true=仅检查，false=实际应用。"}}, "required": ["repoPath", "patchText"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'capture_desktop_screenshot', 'capture_desktop_screenshot', $json$抓取桌面截图用于状态观察与后续 UI 分析。支持按显示器索引截全屏，或通过 region（x,y,w,h）执行局部截图以减少隐私暴露与数据体积。适用于桌面自动化任务中的“观察”阶段、故障复盘取证与人工确认前快照留存。当前为占位实现，后续建议补充系统权限检测、敏感区域脱敏、图片压缩与存储策略。$json$, $json${"type": "object", "properties": {"monitorIndex": {"type": "integer", "description": "显示器索引（可选）。0 表示主屏，1/2... 表示扩展屏；不传时由系统默认策略决定。"}, "region": {"type": "string", "description": "截图区域（可选），格式为 x,y,w,h，例如 100,200,1280,720；不传表示整屏截图。"}}}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string", "description": "执行状态，常见值：success 或 error。"}, "data": {"type": "object", "description": "截图结果对象，通常包含 imagePath、width、height、monitorIndex、region 等字段。"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "capture_desktop_screenshot", "description": "抓取桌面截图用于状态观察与后续 UI 分析。支持按显示器索引截全屏，或通过 region（x,y,w,h）执行局部截图以减少隐私暴露与数据体积。适用于桌面自动化任务中的“观察”阶段、故障复盘取证与人工确认前快照留存。当前为占位实现，后续建议补充系统权限检测、敏感区域脱敏、图片压缩与存储策略。", "version": "1.0.0", "owner": "System", "beanName": "desktopTools", "methodName": "captureDesktopScreenshot", "inputSchema": {"type": "object", "properties": {"monitorIndex": {"type": "integer", "description": "显示器索引（可选）。0 表示主屏，1/2... 表示扩展屏；不传时由系统默认策略决定。"}, "region": {"type": "string", "description": "截图区域（可选），格式为 x,y,w,h，例如 100,200,1280,720；不传表示整屏截图。"}}}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string", "description": "执行状态，常见值：success 或 error。"}, "data": {"type": "object", "description": "截图结果对象，通常包含 imagePath、width、height、monitorIndex、region 等字段。"}}}}$json$::jsonb, NULL),
('local-agent-server', 'checkpoint_plan_state', 'checkpoint_plan_state', $json$创建计划执行检查点快照，用于中断恢复、故障回滚与执行现场重建。调用方应在关键边界（阶段结束、审批前后、批量节点完成后）传入可重建上下文的 checkpointData。系统会对快照生成哈希并持久化，返回 checkpointId 与 snapshotHash；同时可结合审计/SSE形成可观测闭环。$json$, $json${"type": "object", "properties": {"planId": {"type": "string", "description": "计划ID（必填）。检查点归属计划。"}, "phaseId": {"type": "string", "description": "阶段ID（可选）。用于标记检查点所属阶段。"}, "nodeId": {"type": "string", "description": "节点ID（可选）。用于标记检查点所属节点。"}, "checkpointData": {"type": "string", "description": "检查点快照JSON字符串（必填）。应包含恢复执行所需关键字段。"}, "createdBy": {"type": "string", "description": "创建来源（可选）。可填执行器实例、用户、系统模块名等。"}}, "required": ["planId", "checkpointData"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "checkpoint_plan_state", "description": "创建计划执行检查点快照，用于中断恢复、故障回滚与执行现场重建。调用方应在关键边界（阶段结束、审批前后、批量节点完成后）传入可重建上下文的 checkpointData。系统会对快照生成哈希并持久化，返回 checkpointId 与 snapshotHash；同时可结合审计/SSE形成可观测闭环。", "version": "1.0.0", "owner": "System", "beanName": "planCheckpointTools", "methodName": "checkpointPlanState", "inputSchema": {"type": "object", "properties": {"planId": {"type": "string", "description": "计划ID（必填）。检查点归属计划。"}, "phaseId": {"type": "string", "description": "阶段ID（可选）。用于标记检查点所属阶段。"}, "nodeId": {"type": "string", "description": "节点ID（可选）。用于标记检查点所属节点。"}, "checkpointData": {"type": "string", "description": "检查点快照JSON字符串（必填）。应包含恢复执行所需关键字段。"}, "createdBy": {"type": "string", "description": "创建来源（可选）。可填执行器实例、用户、系统模块名等。"}}, "required": ["planId", "checkpointData"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'collect_test_report', 'collect_test_report', $json$聚合测试报告目录并输出结构化统计结果。用于将 surefire/junit 等多来源测试结果统一为机器可读格式，支撑报告生成、失败归因与自动修复循环。当前实现支持基础 XML 解析（tests/failures/errors/skipped）与失败用例提取，输入支持 JSON 数组字符串或逗号分隔目录，便于与不同构建系统集成。$json$, $json${"type": "object", "properties": {"reportDirs": {"type": "string", "description": "报告目录列表（必填）。支持 JSON 数组字符串或逗号分隔路径。"}, "parserType": {"type": "string", "enum": ["junit", "surefire", "auto"], "description": "解析器类型（可选）。auto 会按内容自动识别。"}}, "required": ["reportDirs"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "collect_test_report", "description": "聚合测试报告目录并输出结构化统计结果。用于将 surefire/junit 等多来源测试结果统一为机器可读格式，支撑报告生成、失败归因与自动修复循环。当前实现支持基础 XML 解析（tests/failures/errors/skipped）与失败用例提取，输入支持 JSON 数组字符串或逗号分隔目录，便于与不同构建系统集成。", "version": "1.0.0", "owner": "System", "beanName": "codeOpsTools", "methodName": "collectTestReport", "inputSchema": {"type": "object", "properties": {"reportDirs": {"type": "string", "description": "报告目录列表（必填）。支持 JSON 数组字符串或逗号分隔路径。"}, "parserType": {"type": "string", "enum": ["junit", "surefire", "auto"], "description": "解析器类型（可选）。auto 会按内容自动识别。"}}, "required": ["reportDirs"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'detect_ui_elements', 'detect_ui_elements', $json$识别截图中的 UI 元素（文本、控件、区域）并返回结构化结果，服务于桌面任务定位与自动化操作决策。可指定 detectorType（ocr/uiautomation/hybrid）与 targetHints 提高识别准确度，适用于按钮定位、输入框识别、关键文本抽取等场景。当前为占位实现，后续建议补充坐标标准化、元素类型细分、置信度与多模型融合。$json$, $json${"type": "object", "properties": {"imagePath": {"type": "string", "description": "待识别图片路径（可选）。建议传入 capture_desktop_screenshot 返回的 imagePath。"}, "detectorType": {"type": "string", "enum": ["ocr", "uiautomation", "hybrid"], "description": "识别器类型（可选）。ocr=文本优先；uiautomation=控件树优先；hybrid=融合模式。"}, "targetHints": {"type": "string", "description": "目标提示词（可选）。例如“登录按钮”“搜索输入框”，用于引导识别关注区域。"}}}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string", "description": "执行状态，常见值：success 或 error。"}, "data": {"type": "object", "description": "识别结果对象，通常包含 elements 列表及 imagePath/detectorType/targetHints 等上下文。"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "detect_ui_elements", "description": "识别截图中的 UI 元素（文本、控件、区域）并返回结构化结果，服务于桌面任务定位与自动化操作决策。可指定 detectorType（ocr/uiautomation/hybrid）与 targetHints 提高识别准确度，适用于按钮定位、输入框识别、关键文本抽取等场景。当前为占位实现，后续建议补充坐标标准化、元素类型细分、置信度与多模型融合。", "version": "1.0.0", "owner": "System", "beanName": "desktopTools", "methodName": "detectUiElements", "inputSchema": {"type": "object", "properties": {"imagePath": {"type": "string", "description": "待识别图片路径（可选）。建议传入 capture_desktop_screenshot 返回的 imagePath。"}, "detectorType": {"type": "string", "enum": ["ocr", "uiautomation", "hybrid"], "description": "识别器类型（可选）。ocr=文本优先；uiautomation=控件树优先；hybrid=融合模式。"}, "targetHints": {"type": "string", "description": "目标提示词（可选）。例如“登录按钮”“搜索输入框”，用于引导识别关注区域。"}}}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string", "description": "执行状态，常见值：success 或 error。"}, "data": {"type": "object", "description": "识别结果对象，通常包含 elements 列表及 imagePath/detectorType/targetHints 等上下文。"}}}}$json$::jsonb, NULL),
('local-agent-server', 'emit_plan_event_sse', 'emit_plan_event_sse', $json$向 SSE 客户端推送计划执行事件，实现前端实时可视化更新。适用于节点状态变化、阶段开始/结束、审批事件、测试结果、报告就绪等场景。payload 建议使用结构化 JSON 字符串并携带 planId/phaseId/nodeId 等定位字段，便于前端精准刷新目标卡片或图谱节点。若指定 clientId 不存在，具体行为由服务端会话管理策略决定。$json$, $json${"type": "object", "properties": {"clientId": {"type": "string", "description": "客户端ID（可选）。不传时默认使用 default。"}, "eventType": {"type": "string", "description": "事件类型（必填）。建议使用与审计一致的计划事件枚举名称。"}, "payload": {"type": "string", "description": "事件载荷JSON字符串（必填）。用于前端渲染事件详情。"}}, "required": ["eventType", "payload"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "emit_plan_event_sse", "description": "向 SSE 客户端推送计划执行事件，实现前端实时可视化更新。适用于节点状态变化、阶段开始/结束、审批事件、测试结果、报告就绪等场景。payload 建议使用结构化 JSON 字符串并携带 planId/phaseId/nodeId 等定位字段，便于前端精准刷新目标卡片或图谱节点。若指定 clientId 不存在，具体行为由服务端会话管理策略决定。", "version": "1.0.0", "owner": "System", "beanName": "planEventTools", "methodName": "emitPlanEventSse", "inputSchema": {"type": "object", "properties": {"clientId": {"type": "string", "description": "客户端ID（可选）。不传时默认使用 default。"}, "eventType": {"type": "string", "description": "事件类型（必填）。建议使用与审计一致的计划事件枚举名称。"}, "payload": {"type": "string", "description": "事件载荷JSON字符串（必填）。用于前端渲染事件详情。"}}, "required": ["eventType", "payload"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'git_create_checkpoint', 'git_create_checkpoint', $json$创建代码检查点（commit/stash/tag），用于高风险修改前保存可回退状态。建议在补丁应用前、批量改动前、自动修复循环开始前调用。支持三种模式：commit（自动 add+commit）、stash（含未跟踪文件）、tag（轻量标记）。返回 checkpointId 可直接用于 git_rollback_checkpoint。$json$, $json${"type": "object", "properties": {"repoPath": {"type": "string", "description": "仓库路径（必填）。需为有效 git 仓库目录。"}, "mode": {"type": "string", "enum": ["commit", "stash", "tag"], "description": "检查点模式（必填）。commit/stash/tag 三选一。"}, "message": {"type": "string", "description": "检查点说明（必填）。建议包含任务ID或操作意图，便于追踪。"}}, "required": ["repoPath", "mode", "message"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "git_create_checkpoint", "description": "创建代码检查点（commit/stash/tag），用于高风险修改前保存可回退状态。建议在补丁应用前、批量改动前、自动修复循环开始前调用。支持三种模式：commit（自动 add+commit）、stash（含未跟踪文件）、tag（轻量标记）。返回 checkpointId 可直接用于 git_rollback_checkpoint。", "version": "1.0.0", "owner": "System", "beanName": "codeOpsTools", "methodName": "gitCreateCheckpoint", "inputSchema": {"type": "object", "properties": {"repoPath": {"type": "string", "description": "仓库路径（必填）。需为有效 git 仓库目录。"}, "mode": {"type": "string", "enum": ["commit", "stash", "tag"], "description": "检查点模式（必填）。commit/stash/tag 三选一。"}, "message": {"type": "string", "description": "检查点说明（必填）。建议包含任务ID或操作意图，便于追踪。"}}, "required": ["repoPath", "mode", "message"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'git_rollback_checkpoint', 'git_rollback_checkpoint', $json$将代码仓库回滚到指定检查点，用于自动修复失败后的快速恢复或高风险改动撤销。调用时需提供 checkpointId，mode 可选 hard/soft/mixed，分别对应不同回滚强度。建议在生产链路接入审批或二次确认，避免误回滚造成工作区损失。$json$, $json${"type": "object", "properties": {"repoPath": {"type": "string", "description": "仓库路径（必填）。用于执行 git reset。"}, "checkpointId": {"type": "string", "description": "检查点ID（必填）。可为 commit hash、tag 等可解析标识。"}, "mode": {"type": "string", "enum": ["hard", "soft", "mixed"], "description": "回滚模式（可选）。hard=强制回滚工作区，soft/mixed=保留部分改动。"}}, "required": ["repoPath", "checkpointId"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "git_rollback_checkpoint", "description": "将代码仓库回滚到指定检查点，用于自动修复失败后的快速恢复或高风险改动撤销。调用时需提供 checkpointId，mode 可选 hard/soft/mixed，分别对应不同回滚强度。建议在生产链路接入审批或二次确认，避免误回滚造成工作区损失。", "version": "1.0.0", "owner": "System", "beanName": "codeOpsTools", "methodName": "gitRollbackCheckpoint", "inputSchema": {"type": "object", "properties": {"repoPath": {"type": "string", "description": "仓库路径（必填）。用于执行 git reset。"}, "checkpointId": {"type": "string", "description": "检查点ID（必填）。可为 commit hash、tag 等可解析标识。"}, "mode": {"type": "string", "enum": ["hard", "soft", "mixed"], "description": "回滚模式（可选）。hard=强制回滚工作区，soft/mixed=保留部分改动。"}}, "required": ["repoPath", "checkpointId"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'image_search', 'image_search', $json$执行互联网图片搜索。当用户明确要求寻找某种图片、照片、插图，或者需要视觉参考资料时调用。输入描述性的关键词，返回相关图片的 URL 和标题。$json$, $json${"type": "object", "properties": {"query": {"type": "string", "description": "图片搜索关键词（必填）。可包含风格、主体、场景等限定信息，例如“赛博朋克 城市 夜景 插画”。"}}, "required": ["query"]}$json$::jsonb, $json${"type": "object", "properties": {"images": {"type": "array", "description": "图片结果列表，通常包含图片 URL、来源页面、标题等字段。"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "image_search", "description": "执行互联网图片搜索。当用户明确要求寻找某种图片、照片、插图，或者需要视觉参考资料时调用。输入描述性的关键词，返回相关图片的 URL 和标题。", "version": "1.0.0", "owner": "System", "beanName": "searchTools", "methodName": "image_search", "inputSchema": {"type": "object", "properties": {"query": {"type": "string", "description": "图片搜索关键词（必填）。可包含风格、主体、场景等限定信息，例如“赛博朋克 城市 夜景 插画”。"}}, "required": ["query"]}, "outputSchema": {"type": "object", "properties": {"images": {"type": "array", "description": "图片结果列表，通常包含图片 URL、来源页面、标题等字段。"}}}}$json$::jsonb, NULL),
('local-agent-server', 'lens_search', 'lens_search', $json$执行以图搜图（Google Lens）检索。当用户提供图片 URL 并希望识别图片内容、寻找相似图片、定位商品或获取相关背景信息时调用。该工具适用于“图像反查”场景，可作为 web_search/image_search 的补充入口。调用前请确保 URL 可公网访问且为有效图片资源链接。$json$, $json${"type": "object", "properties": {"url": {"type": "string", "description": "图片 URL（必填）。需要可公网访问的完整链接（http/https）。"}}, "required": ["url"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string", "description": "执行状态，常见值：success 或 error。"}, "data": {"type": "object", "description": "以图搜图结果对象，字段由第三方接口返回决定，常见包含 visualMatches/knowledgeGraph 等。"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "lens_search", "description": "执行以图搜图（Google Lens）检索。当用户提供图片 URL 并希望识别图片内容、寻找相似图片、定位商品或获取相关背景信息时调用。该工具适用于“图像反查”场景，可作为 web_search/image_search 的补充入口。调用前请确保 URL 可公网访问且为有效图片资源链接。", "version": "1.0.0", "owner": "System", "beanName": "searchTools", "methodName": "lens_search", "inputSchema": {"type": "object", "properties": {"url": {"type": "string", "description": "图片 URL（必填）。需要可公网访问的完整链接（http/https）。"}}, "required": ["url"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string", "description": "执行状态，常见值：success 或 error。"}, "data": {"type": "object", "description": "以图搜图结果对象，字段由第三方接口返回决定，常见包含 visualMatches/knowledgeGraph 等。"}}}}$json$::jsonb, NULL),
('local-agent-server', 'list_phase_nodes', 'list_phase_nodes', $json$按计划与阶段查询节点明细列表。用于阶段执行前拉取待执行节点、前端渲染流程图、故障排查定位具体节点状态。返回结果通常包含节点ID、类型、状态、依赖关系、重试信息等字段，是阶段调度与可观测面板的基础数据来源。建议与 query_plan_progress 结合使用：前者看节点级明细，后者看全局状态聚合。$json$, $json${"type": "object", "properties": {"planId": {"type": "string", "description": "计划ID（必填）。用于限定查询范围到指定计划。"}, "phaseId": {"type": "string", "description": "阶段ID（必填）。用于定位计划中的具体阶段。"}}, "required": ["planId", "phaseId"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "array"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "list_phase_nodes", "description": "按计划与阶段查询节点明细列表。用于阶段执行前拉取待执行节点、前端渲染流程图、故障排查定位具体节点状态。返回结果通常包含节点ID、类型、状态、依赖关系、重试信息等字段，是阶段调度与可观测面板的基础数据来源。建议与 query_plan_progress 结合使用：前者看节点级明细，后者看全局状态聚合。", "version": "1.0.0", "owner": "System", "beanName": "planNodeTools", "methodName": "listPhaseNodes", "inputSchema": {"type": "object", "properties": {"planId": {"type": "string", "description": "计划ID（必填）。用于限定查询范围到指定计划。"}, "phaseId": {"type": "string", "description": "阶段ID（必填）。用于定位计划中的具体阶段。"}}, "required": ["planId", "phaseId"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "array"}}}}$json$::jsonb, NULL),
('local-agent-server', 'load_plan_blueprint', 'load_plan_blueprint', $json$读取并校验计划蓝图。传入 planId 必选，planVersion 可选：若传则读取指定版本，不传则读取最新版本。读取后会执行结构校验（如阶段/节点必填字段、依赖关系与 DAG 有效性等），并将结果写入审计链路；校验通过返回蓝图与元信息，校验失败返回错误信息并记录失败事件。适用于执行前预检、蓝图回放、可视化加载等场景。$json$, $json${"type": "object", "properties": {"planId": {"type": "string", "description": "计划ID（必填）。用于定位目标计划蓝图。"}, "planVersion": {"type": "integer", "description": "计划版本（可选）。不传时默认读取最新版本。"}}, "required": ["planId"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}, "message": {"type": "string"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.1.0', false, 'LOW', $json${"name": "load_plan_blueprint", "description": "读取并校验计划蓝图。传入 planId 必选，planVersion 可选：若传则读取指定版本，不传则读取最新版本。读取后会执行结构校验（如阶段/节点必填字段、依赖关系与 DAG 有效性等），并将结果写入审计链路；校验通过返回蓝图与元信息，校验失败返回错误信息并记录失败事件。适用于执行前预检、蓝图回放、可视化加载等场景。", "version": "1.1.0", "owner": "System", "beanName": "planBlueprintTools", "methodName": "loadPlanBlueprint", "inputSchema": {"type": "object", "properties": {"planId": {"type": "string", "description": "计划ID（必填）。用于定位目标计划蓝图。"}, "planVersion": {"type": "integer", "description": "计划版本（可选）。不传时默认读取最新版本。"}}, "required": ["planId"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}, "message": {"type": "string"}}}}$json$::jsonb, NULL),
('local-agent-server', 'manage_knowledge_base', 'manage_knowledge_base', $json$用于管理系统的 RAG (检索增强生成) 知识库。当用户提供长篇文档、重要资料需要长期存档时调用 INSERT 写入；当你需要回答特定领域问题、回忆之前存储的专属知识时调用 QUERY 进行语义向量检索。$json$, $json${"type": "object", "properties": {"action": {"type": "string", "enum": ["INSERT", "QUERY"], "description": "操作类型（必填）。可选值：INSERT=新增知识；QUERY=检索知识。"}, "title": {"type": "string", "description": "知识标题。action=INSERT 时必填，用于标识该知识片段主题。"}, "content": {"type": "string", "description": "知识正文内容。action=INSERT 时必填，支持长文本。"}, "sourceType": {"type": "string", "enum": ["FILE", "WEB_SEARCH", "MANUAL_INPUT"], "description": "来源类型。action=INSERT 时建议提供。可选值：FILE=本地文件；WEB_SEARCH=网络检索；MANUAL_INPUT=人工输入。"}, "sourcePath": {"type": "string", "description": "来源路径或来源标识。可选，例如文件路径、URL、业务来源ID。"}, "query": {"type": "string", "description": "检索关键词。action=QUERY 时必填，用于语义检索。"}}, "required": ["action"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string", "description": "执行状态，常见值：success 或 error。"}, "data": {"type": "array", "description": "操作结果。QUERY 时通常为知识片段列表；INSERT 时通常为成功提示。"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "manage_knowledge_base", "description": "用于管理系统的 RAG (检索增强生成) 知识库。当用户提供长篇文档、重要资料需要长期存档时调用 INSERT 写入；当你需要回答特定领域问题、回忆之前存储的专属知识时调用 QUERY 进行语义向量检索。", "version": "1.0.0", "owner": "System", "beanName": "knowledgeBaseTools", "methodName": "manageKnowledgeBase", "inputSchema": {"type": "object", "properties": {"action": {"type": "string", "enum": ["INSERT", "QUERY"], "description": "操作类型（必填）。可选值：INSERT=新增知识；QUERY=检索知识。"}, "title": {"type": "string", "description": "知识标题。action=INSERT 时必填，用于标识该知识片段主题。"}, "content": {"type": "string", "description": "知识正文内容。action=INSERT 时必填，支持长文本。"}, "sourceType": {"type": "string", "enum": ["FILE", "WEB_SEARCH", "MANUAL_INPUT"], "description": "来源类型。action=INSERT 时建议提供。可选值：FILE=本地文件；WEB_SEARCH=网络检索；MANUAL_INPUT=人工输入。"}, "sourcePath": {"type": "string", "description": "来源路径或来源标识。可选，例如文件路径、URL、业务来源ID。"}, "query": {"type": "string", "description": "检索关键词。action=QUERY 时必填，用于语义检索。"}}, "required": ["action"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string", "description": "执行状态，常见值：success 或 error。"}, "data": {"type": "array", "description": "操作结果。QUERY 时通常为知识片段列表；INSERT 时通常为成功提示。"}}}}$json$::jsonb, NULL),
('local-agent-server', 'manage_log', 'manage_log', $json$用于查询和管理系统的运行日志。当需要排查错误、审计系统行为、查看工具调用历史或用户操作记录时调用。支持按日志类型、模块、时间段进行 QUERY 查询，也支持 INSERT 写入自定义日志或 DELETE 清理过期日志。$json$, $json${"type": "object", "properties": {"action": {"type": "string", "enum": ["INSERT", "QUERY", "DELETE"], "description": "操作类型（必填）。可选值：INSERT=新增日志；QUERY=查询日志；DELETE=删除日志。"}, "logType": {"type": "string", "enum": ["LUNA_OUTPUT", "TOOL_CALL", "ERROR", "SELF_UPDATE", "SYSTEM_EVENT", "API_CALL"], "description": "日志类型。可选值：LUNA_OUTPUT=Luna输出；TOOL_CALL=工具调用；ERROR=系统异常；SELF_UPDATE=自我更新；SYSTEM_EVENT=系统行为；API_CALL=接口调用。"}, "module": {"type": "string", "description": "日志所属模块（可选），例如 chat / tool / system。"}, "content": {"type": "string", "description": "日志内容文本。action=INSERT 时建议提供。"}, "startTime": {"type": "string", "description": "查询开始时间（可选），格式：yyyy-MM-dd HH:mm:ss。"}, "endTime": {"type": "string", "description": "查询结束时间（可选），格式：yyyy-MM-dd HH:mm:ss。"}, "limit": {"type": "integer", "description": "返回条数上限（可选），默认通常为 50。"}, "id": {"type": "integer", "description": "日志ID。action=DELETE 且按单条删除时使用。"}, "beforeTime": {"type": "string", "description": "按时间批量删除阈值（可选），删除该时间之前日志，格式：yyyy-MM-dd HH:mm:ss。"}}, "required": ["action"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string", "description": "执行状态，常见值：success 或 error。"}, "data": {"type": "object", "description": "返回数据。QUERY 时为日志对象列表；INSERT/DELETE 时为结果信息。"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "manage_log", "description": "用于查询和管理系统的运行日志。当需要排查错误、审计系统行为、查看工具调用历史或用户操作记录时调用。支持按日志类型、模块、时间段进行 QUERY 查询，也支持 INSERT 写入自定义日志或 DELETE 清理过期日志。", "version": "1.0.0", "owner": "System", "beanName": "logTools", "methodName": "manageLog", "inputSchema": {"type": "object", "properties": {"action": {"type": "string", "enum": ["INSERT", "QUERY", "DELETE"], "description": "操作类型（必填）。可选值：INSERT=新增日志；QUERY=查询日志；DELETE=删除日志。"}, "logType": {"type": "string", "enum": ["LUNA_OUTPUT", "TOOL_CALL", "ERROR", "SELF_UPDATE", "SYSTEM_EVENT", "API_CALL"], "description": "日志类型。可选值：LUNA_OUTPUT=Luna输出；TOOL_CALL=工具调用；ERROR=系统异常；SELF_UPDATE=自我更新；SYSTEM_EVENT=系统行为；API_CALL=接口调用。"}, "module": {"type": "string", "description": "日志所属模块（可选），例如 chat / tool / system。"}, "content": {"type": "string", "description": "日志内容文本。action=INSERT 时建议提供。"}, "startTime": {"type": "string", "description": "查询开始时间（可选），格式：yyyy-MM-dd HH:mm:ss。"}, "endTime": {"type": "string", "description": "查询结束时间（可选），格式：yyyy-MM-dd HH:mm:ss。"}, "limit": {"type": "integer", "description": "返回条数上限（可选），默认通常为 50。"}, "id": {"type": "integer", "description": "日志ID。action=DELETE 且按单条删除时使用。"}, "beforeTime": {"type": "string", "description": "按时间批量删除阈值（可选），删除该时间之前日志，格式：yyyy-MM-dd HH:mm:ss。"}}, "required": ["action"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string", "description": "执行状态，常见值：success 或 error。"}, "data": {"type": "object", "description": "返回数据。QUERY 时为日志对象列表；INSERT/DELETE 时为结果信息。"}}}}$json$::jsonb, NULL),
('local-agent-server', 'manage_memory', 'manage_memory', $json$用于管理 AI 与用户对话的长期记忆。当需要记住用户的个人画像、对话总结或关键事实以便未来对话使用时调用。支持 INSERT(新增)、QUERY(查询)、UPDATE(更新)、DELETE(删除)。$json$, $json${"type": "object", "properties": {"action": {"type": "string", "enum": ["INSERT", "QUERY", "UPDATE", "DELETE"], "description": "操作类型（必填）。可选值：INSERT=新增记忆；QUERY=查询记忆；UPDATE=更新记忆；DELETE=删除记忆。"}, "id": {"type": "integer", "description": "记忆ID。action=UPDATE 或 DELETE 时必填。"}, "mode": {"type": "string", "enum": ["PUT", "PATCH"], "description": "更新模式。action=UPDATE 时必填。可选值：PUT=全量替换；PATCH=部分更新。"}, "sessionId": {"type": "string", "description": "会话标识（可选），用于关联记忆归属会话。"}, "memoryType": {"type": "string", "enum": ["FACT", "PREFERENCE", "SUMMARY", "REFLECTION"], "description": "记忆类型。可选值：FACT=客观事实；PREFERENCE=用户偏好；SUMMARY=对话摘要；REFLECTION=自我反思。"}, "content": {"type": "string", "description": "记忆内容文本。action=INSERT 时通常必填。"}, "weight": {"type": "integer", "description": "记忆权重（可选），数值越大表示越重要，默认 1。"}, "hardDelete": {"type": "boolean", "description": "删除方式（可选，仅 action=DELETE 时生效）。true=物理删除；false/不传=按系统默认删除策略。"}}, "required": ["action"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string", "description": "执行状态，常见值：success 或 error。"}, "data": {"type": "object", "description": "返回数据。可能是单条 Memory、Memory 列表或操作结果信息。"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "manage_memory", "description": "用于管理 AI 与用户对话的长期记忆。当需要记住用户的个人画像、对话总结或关键事实以便未来对话使用时调用。支持 INSERT(新增)、QUERY(查询)、UPDATE(更新)、DELETE(删除)。", "version": "1.0.0", "owner": "System", "beanName": "memoryTools", "methodName": "manageMemory", "inputSchema": {"type": "object", "properties": {"action": {"type": "string", "enum": ["INSERT", "QUERY", "UPDATE", "DELETE"], "description": "操作类型（必填）。可选值：INSERT=新增记忆；QUERY=查询记忆；UPDATE=更新记忆；DELETE=删除记忆。"}, "id": {"type": "integer", "description": "记忆ID。action=UPDATE 或 DELETE 时必填。"}, "mode": {"type": "string", "enum": ["PUT", "PATCH"], "description": "更新模式。action=UPDATE 时必填。可选值：