ng", "description": "偏好键名（例如 nickname、language、style）。INSERT/UPDATE 时建议提供。"}, "prefValue": {"type": "string", "description": "偏好值（例如 Luna、zh-CN、formal）。INSERT/UPDATE 时建议提供。"}, "description": {"type": "string", "description": "偏好说明或备注（可选），用于增强语义理解。"}, "hardDelete": {"type": "boolean", "description": "删除方式（可选，仅 action=DELETE 时生效）。true=物理删除；false/不传=按系统默认删除策略。"}}, "required": ["action"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string", "description": "执行状态，常见值：success 或 error。"}, "data": {"type": "object", "description": "返回数据。可能是单条 UserPreference、列表或操作结果信息。"}}}}$json$::jsonb, NULL),
('local-agent-server', 'news_search', 'news_search', $json$执行互联网新闻搜索。当用户询问最近发生的事件、时事热点、行业动态或特定主题的最新报道时调用。返回包含标题、来源和发布时间的新闻列表。$json$, $json${"type": "object", "properties": {"query": {"type": "string", "description": "新闻搜索关键词（必填）。建议包含事件主体与时间范围，例如“AI 芯片 发布会 本周”。"}}, "required": ["query"]}$json$::jsonb, $json${"type": "object", "properties": {"news": {"type": "array", "description": "新闻结果列表，通常包含标题、来源、发布时间、链接、摘要等字段。"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "news_search", "description": "执行互联网新闻搜索。当用户询问最近发生的事件、时事热点、行业动态或特定主题的最新报道时调用。返回包含标题、来源和发布时间的新闻列表。", "version": "1.0.0", "owner": "System", "beanName": "searchTools", "methodName": "news_search", "inputSchema": {"type": "object", "properties": {"query": {"type": "string", "description": "新闻搜索关键词（必填）。建议包含事件主体与时间范围，例如“AI 芯片 发布会 本周”。"}}, "required": ["query"]}, "outputSchema": {"type": "object", "properties": {"news": {"type": "array", "description": "新闻结果列表，通常包含标题、来源、发布时间、链接、摘要等字段。"}}}}$json$::jsonb, NULL),
('local-agent-server', 'open_browser_with_file', 'open_browser_with_file', $json$调用系统默认浏览器打开本地报告文件，用于在报告生成后快速展示结果。通常与 write_html_report_file 联动：先写文件，再尝试打开。若运行环境不支持桌面能力（如无图形界面）或文件不存在，工具会返回失败标记但不应中断主任务链，方便上层继续以链接方式提供访问。$json$, $json${"type": "object", "properties": {"reportPath": {"type": "string", "description": "本地报告文件路径（必填）。应为可访问的 HTML 文件绝对或相对路径。"}}, "required": ["reportPath"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "open_browser_with_file", "description": "调用系统默认浏览器打开本地报告文件，用于在报告生成后快速展示结果。通常与 write_html_report_file 联动：先写文件，再尝试打开。若运行环境不支持桌面能力（如无图形界面）或文件不存在，工具会返回失败标记但不应中断主任务链，方便上层继续以链接方式提供访问。", "version": "1.0.0", "owner": "System", "beanName": "planReportTools", "methodName": "openBrowserWithFile", "inputSchema": {"type": "object", "properties": {"reportPath": {"type": "string", "description": "本地报告文件路径（必填）。应为可访问的 HTML 文件绝对或相对路径。"}}, "required": ["reportPath"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'query_plan_progress', 'query_plan_progress', $json$查询计划级执行进度聚合信息，返回节点总数与按状态分布统计。适用于前端看板轮询、任务总览页展示、SSE 丢包后的状态补偿。该工具强调全局视角，不替代节点明细查询；建议与 list_phase_nodes、事件流共同使用以获得完整可观测性。$json$, $json${"type": "object", "properties": {"planId": {"type": "string", "description": "计划ID（必填）。用于统计该计划下所有节点状态。"}}, "required": ["planId"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "query_plan_progress", "description": "查询计划级执行进度聚合信息，返回节点总数与按状态分布统计。适用于前端看板轮询、任务总览页展示、SSE 丢包后的状态补偿。该工具强调全局视角，不替代节点明细查询；建议与 list_phase_nodes、事件流共同使用以获得完整可观测性。", "version": "1.0.0", "owner": "System", "beanName": "planNodeTools", "methodName": "queryPlanProgress", "inputSchema": {"type": "object", "properties": {"planId": {"type": "string", "description": "计划ID（必填）。用于统计该计划下所有节点状态。"}}, "required": ["planId"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'read_repo_tree', 'read_repo_tree', $json$读取代码仓库目录树结构，用于任务规划、影响面评估与文件定位。支持 maxDepth 限制遍历深度，支持 includeHidden 控制是否包含隐藏文件。工具会忽略常见大型目录（如 .git、node_modules、target）以提升性能。适用于代码任务前置理解阶段，帮助模型快速掌握模块边界与目录布局。$json$, $json${"type": "object", "properties": {"repoPath": {"type": "string", "description": "仓库根路径（必填）。需位于受控工作区内。"}, "maxDepth": {"type": "integer", "description": "最大遍历深度（可选）。用于控制扫描范围与性能开销。"}, "includeHidden": {"type": "boolean", "description": "是否包含隐藏文件/目录（可选）。true=包含，false=忽略。"}}, "required": ["repoPath"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "read_repo_tree", "description": "读取代码仓库目录树结构，用于任务规划、影响面评估与文件定位。支持 maxDepth 限制遍历深度，支持 includeHidden 控制是否包含隐藏文件。工具会忽略常见大型目录（如 .git、node_modules、target）以提升性能。适用于代码任务前置理解阶段，帮助模型快速掌握模块边界与目录布局。", "version": "1.0.0", "owner": "System", "beanName": "codeOpsTools", "methodName": "readRepoTree", "inputSchema": {"type": "object", "properties": {"repoPath": {"type": "string", "description": "仓库根路径（必填）。需位于受控工作区内。"}, "maxDepth": {"type": "integer", "description": "最大遍历深度（可选）。用于控制扫描范围与性能开销。"}, "includeHidden": {"type": "boolean", "description": "是否包含隐藏文件/目录（可选）。true=包含，false=忽略。"}}, "required": ["repoPath"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'read_source_file', 'read_source_file', $json$读取源码文件内容，供代码理解、补丁生成、失败分析与测试修复步骤使用。支持 encoding 与 maxBytes，避免大文件读取导致性能问题或上下文超限。建议调用前先通过 read_repo_tree 确认路径，再按需精确读取目标文件。$json$, $json${"type": "object", "properties": {"filePath": {"type": "string", "description": "文件路径（必填）。需位于受控工作区内。"}, "encoding": {"type": "string", "description": "文件编码（可选）。默认 UTF-8。"}, "maxBytes": {"type": "integer", "description": "最大读取字节数（可选）。超过限制将返回错误。"}}, "required": ["filePath"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "read_source_file", "description": "读取源码文件内容，供代码理解、补丁生成、失败分析与测试修复步骤使用。支持 encoding 与 maxBytes，避免大文件读取导致性能问题或上下文超限。建议调用前先通过 read_repo_tree 确认路径，再按需精确读取目标文件。", "version": "1.0.0", "owner": "System", "beanName": "codeOpsTools", "methodName": "readSourceFile", "inputSchema": {"type": "object", "properties": {"filePath": {"type": "string", "description": "文件路径（必填）。需位于受控工作区内。"}, "encoding": {"type": "string", "description": "文件编码（可选）。默认 UTF-8。"}, "maxBytes": {"type": "integer", "description": "最大读取字节数（可选）。超过限制将返回错误。"}}, "required": ["filePath"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'record_plan_audit_log', 'record_plan_audit_log', $json$记录计划执行审计事件并持久化到事件日志表。用于沉淀阶段切换、节点状态流转、重规划、检查点、审批请求与结果等关键轨迹，支撑可视化回放、问题排查与合规审计。调用时应使用标准 eventType 与 level 枚举；eventPayload 建议传结构化 JSON 字符串，便于后续检索、聚合统计与告警分析。$json$, $json${"type": "object", "properties": {"planId": {"type": "string", "description": "计划ID（必填）。审计事件归属的主键。"}, "phaseId": {"type": "string", "description": "阶段ID（可选）。当事件与特定阶段相关时填写。"}, "nodeId": {"type": "string", "description": "节点ID（可选）。当事件与特定节点相关时填写。"}, "level": {"type": "string", "enum": ["INFO", "WARN", "ERROR"], "description": "事件级别（必填）。用于区分普通信息、告警与错误。"}, "eventType": {"type": "string", "enum": ["PLAN_CREATED", "PLAN_PHASE_STARTED", "PLAN_PHASE_FINISHED", "PLAN_NODE_RUNNING", "PLAN_NODE_SUCCESS", "PLAN_NODE_FAILED", "PLAN_REPLANNED", "PLAN_FINISHED", "PLAN_REPORT_READY", "PLAN_CODE_PATCH_READY", "PLAN_TEST_RESULT", "APPROVAL_REQUEST", "APPROVAL_RESULT", "PLAN_CHECKPOINT_CREATED", "PLAN_BLUEPRINT_VALIDATED", "PLAN_BLUEPRINT_INVALID"], "description": "事件类型（必填）。必须使用系统支持的计划事件枚举。"}, "eventPayload": {"type": "string", "description": "事件载荷JSON字符串（必填）。建议包含上下文字段，如状态、耗时、原因等。"}, "traceId": {"type": "string", "description": "链路追踪ID（可选）。用于跨服务日志关联。"}}, "required": ["planId", "level", "eventType", "eventPayload"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.1.0', false, 'LOW', $json${"name": "record_plan_audit_log", "description": "记录计划执行审计事件并持久化到事件日志表。用于沉淀阶段切换、节点状态流转、重规划、检查点、审批请求与结果等关键轨迹，支撑可视化回放、问题排查与合规审计。调用时应使用标准 eventType 与 level 枚举；eventPayload 建议传结构化 JSON 字符串，便于后续检索、聚合统计与告警分析。", "version": "1.1.0", "owner": "System", "beanName": "planEventTools", "methodName": "recordPlanAuditLog", "inputSchema": {"type": "object", "properties": {"planId": {"type": "string", "description": "计划ID（必填）。审计事件归属的主键。"}, "phaseId": {"type": "string", "description": "阶段ID（可选）。当事件与特定阶段相关时填写。"}, "nodeId": {"type": "string", "description": "节点ID（可选）。当事件与特定节点相关时填写。"}, "level": {"type": "string", "enum": ["INFO", "WARN", "ERROR"], "description": "事件级别（必填）。用于区分普通信息、告警与错误。"}, "eventType": {"type": "string", "enum": ["PLAN_CREATED", "PLAN_PHASE_STARTED", "PLAN_PHASE_FINISHED", "PLAN_NODE_RUNNING", "PLAN_NODE_SUCCESS", "PLAN_NODE_FAILED", "PLAN_REPLANNED", "PLAN_FINISHED", "PLAN_REPORT_READY", "PLAN_CODE_PATCH_READY", "PLAN_TEST_RESULT", "APPROVAL_REQUEST", "APPROVAL_RESULT", "PLAN_CHECKPOINT_CREATED", "PLAN_BLUEPRINT_VALIDATED", "PLAN_BLUEPRINT_INVALID"], "description": "事件类型（必填）。必须使用系统支持的计划事件枚举。"}, "eventPayload": {"type": "string", "description": "事件载荷JSON字符串（必填）。建议包含上下文字段，如状态、耗时、原因等。"}, "traceId": {"type": "string", "description": "链路追踪ID（可选）。用于跨服务日志关联。"}}, "required": ["planId", "level", "eventType", "eventPayload"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'release_execution_lock', 'release_execution_lock', $json$释放分布式执行锁。用于在任务完成、失败补偿、超时回收等时机主动解锁，避免后续流程被锁阻塞。该接口要求 lockKey 与 owner 同时匹配，防止误释放其他执行实例持有的锁。建议与 acquire_execution_lock 严格配对，并在业务 finally 块中调用；即使主流程失败也应尝试释放，以保障系统可用性与调度吞吐。$json$, $json${"type": "object", "properties": {"lockKey": {"type": "string", "description": "锁键（必填）。需与加锁时使用的 lockKey 完全一致。"}, "owner": {"type": "string", "description": "锁持有者标识（必填）。需与加锁时 owner 一致，否则不会释放。"}}, "required": ["lockKey", "owner"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "release_execution_lock", "description": "释放分布式执行锁。用于在任务完成、失败补偿、超时回收等时机主动解锁，避免后续流程被锁阻塞。该接口要求 lockKey 与 owner 同时匹配，防止误释放其他执行实例持有的锁。建议与 acquire_execution_lock 严格配对，并在业务 finally 块中调用；即使主流程失败也应尝试释放，以保障系统可用性与调度吞吐。", "version": "1.0.0", "owner": "System", "beanName": "executionLockTools", "methodName": "releaseExecutionLock", "inputSchema": {"type": "object", "properties": {"lockKey": {"type": "string", "description": "锁键（必填）。需与加锁时使用的 lockKey 完全一致。"}, "owner": {"type": "string", "description": "锁持有者标识（必填）。需与加锁时 owner 一致，否则不会释放。"}}, "required": ["lockKey", "owner"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'run_build_command', 'run_build_command', $json$执行项目构建命令（如 mvn/gradle），用于验证代码改动后是否可成功编译打包。该工具适合放在补丁应用后或提交前的质量门禁步骤。调用方应提供受控工作目录与命令，并设置 timeoutSec 防止长时间阻塞。返回 exitCode 与输出摘要，便于快速定位构建失败原因。$json$, $json${"type": "object", "properties": {"workDir": {"type": "string", "description": "执行目录（必填）。通常为项目根目录。"}, "command": {"type": "string", "description": "构建命令（必填）。需符合系统命令白名单策略。"}, "timeoutSec": {"type": "integer", "description": "超时秒数（可选）。超过后将强制终止进程。"}}, "required": ["workDir", "command"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "run_build_command", "description": "执行项目构建命令（如 mvn/gradle），用于验证代码改动后是否可成功编译打包。该工具适合放在补丁应用后或提交前的质量门禁步骤。调用方应提供受控工作目录与命令，并设置 timeoutSec 防止长时间阻塞。返回 exitCode 与输出摘要，便于快速定位构建失败原因。", "version": "1.0.0", "owner": "System", "beanName": "codeOpsTools", "methodName": "runBuildCommand", "inputSchema": {"type": "object", "properties": {"workDir": {"type": "string", "description": "执行目录（必填）。通常为项目根目录。"}, "command": {"type": "string", "description": "构建命令（必填）。需符合系统命令白名单策略。"}, "timeoutSec": {"type": "integer", "description": "超时秒数（可选）。超过后将强制终止进程。"}}, "required": ["workDir", "command"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'run_format_command', 'run_format_command', $json$执行代码格式化命令，统一代码风格并减少无效 diff。常用于补丁应用后、提交前或自动修复闭环中的收尾步骤。调用时应明确 workDir 与格式化命令，并设置 timeoutSec 防止大仓库阻塞。输出可用于判断格式化是否成功及后续是否需要再次构建/测试。$json$, $json${"type": "object", "properties": {"workDir": {"type": "string", "description": "执行目录（必填）。通常为项目根目录或目标模块目录。"}, "command": {"type": "string", "description": "格式化命令（必填）。需符合系统命令白名单策略。"}, "timeoutSec": {"type": "integer", "description": "超时秒数（可选）。用于控制长任务执行时间。"}}, "required": ["workDir", "command"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "run_format_command", "description": "执行代码格式化命令，统一代码风格并减少无效 diff。常用于补丁应用后、提交前或自动修复闭环中的收尾步骤。调用时应明确 workDir 与格式化命令，并设置 timeoutSec 防止大仓库阻塞。输出可用于判断格式化是否成功及后续是否需要再次构建/测试。", "version": "1.0.0", "owner": "System", "beanName": "codeOpsTools", "methodName": "runFormatCommand", "inputSchema": {"type": "object", "properties": {"workDir": {"type": "string", "description": "执行目录（必填）。通常为项目根目录或目标模块目录。"}, "command": {"type": "string", "description": "格式化命令（必填）。需符合系统命令白名单策略。"}, "timeoutSec": {"type": "integer", "description": "超时秒数（可选）。用于控制长任务执行时间。"}}, "required": ["workDir", "command"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'run_lint_command', 'run_lint_command', $json$执行静态检查命令（lint/规则扫描），用于在构建和测试前提前发现风格问题与潜在缺陷。适合接入自动修复流水线和 CI 质量门禁。建议统一命令模板并设置 timeoutSec 控制执行时长。返回结果可用于提取问题清单，驱动后续修复策略决策。$json$, $json${"type": "object", "properties": {"workDir": {"type": "string", "description": "执行目录（必填）。通常为项目根目录或模块目录。"}, "command": {"type": "string", "description": "静态检查命令（必填）。需符合系统命令白名单策略。"}, "timeoutSec": {"type": "integer", "description": "超时秒数（可选）。超时将中断执行并返回错误。"}}, "required": ["workDir", "command"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "run_lint_command", "description": "执行静态检查命令（lint/规则扫描），用于在构建和测试前提前发现风格问题与潜在缺陷。适合接入自动修复流水线和 CI 质量门禁。建议统一命令模板并设置 timeoutSec 控制执行时长。返回结果可用于提取问题清单，驱动后续修复策略决策。", "version": "1.0.0", "owner": "System", "beanName": "codeOpsTools", "methodName": "runLintCommand", "inputSchema": {"type": "object", "properties": {"workDir": {"type": "string", "description": "执行目录（必填）。通常为项目根目录或模块目录。"}, "command": {"type": "string", "description": "静态检查命令（必填）。需符合系统命令白名单策略。"}, "timeoutSec": {"type": "integer", "description": "超时秒数（可选）。超时将中断执行并返回错误。"}}, "required": ["workDir", "command"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'run_test_command', 'run_test_command', $json$执行测试命令并返回结构化结果摘要。适用于代码改动后的回归验证、失败重跑与自动修复闭环。调用方需传入 workDir 与测试命令（如 mvn test / gradle test），并可设置 timeoutSec 防止卡死。返回 exitCode、输出尾部与耗时，便于后续失败归因与自动决策。$json$, $json${"type": "object", "properties": {"workDir": {"type": "string", "description": "执行目录（必填）。通常为项目根目录。"}, "command": {"type": "string", "description": "测试命令（必填）。需符合系统命令白名单策略。"}, "timeoutSec": {"type": "integer", "description": "超时秒数（可选）。用于防止测试进程无限阻塞。"}}, "required": ["workDir", "command"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "run_test_command", "description": "执行测试命令并返回结构化结果摘要。适用于代码改动后的回归验证、失败重跑与自动修复闭环。调用方需传入 workDir 与测试命令（如 mvn test / gradle test），并可设置 timeoutSec 防止卡死。返回 exitCode、输出尾部与耗时，便于后续失败归因与自动决策。", "version": "1.0.0", "owner": "System", "beanName": "codeOpsTools", "methodName": "runTestCommand", "inputSchema": {"type": "object", "properties": {"workDir": {"type": "string", "description": "执行目录（必填）。通常为项目根目录。"}, "command": {"type": "string", "description": "测试命令（必填）。需符合系统命令白名单策略。"}, "timeoutSec": {"type": "integer", "description": "超时秒数（可选）。用于防止测试进程无限阻塞。"}}, "required": ["workDir", "command"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'save_plan_blueprint', 'save_plan_blueprint', $json$保存全局规划蓝图（PlanBlueprint）到持久层，支持按 planId + planVersion 幂等写入。适用于大模型完成一次性全局规划后，将阶段划分、节点拓扑、资源提示与风险信息版本化落库。若同版本已存在则执行更新，不存在则执行插入。建议在规划阶段结束后立即调用，确保后续执行器按冻结版本推进。$json$, $json${"type": "object", "properties": {"planId": {"type": "string", "description": "计划ID（必填）。用于标识蓝图归属计划。"}, "planVersion": {"type": "integer", "description": "计划版本号（必填）。用于版本控制与回溯。"}, "blueprintJson": {"type": "string", "description": "蓝图JSON字符串（必填）。包含 phases/nodes/edges 等核心结构。"}, "generatedByModel": {"type": "string", "description": "生成模型标识（可选）。用于审计与效果分析。"}, "generatedAt": {"type": "string", "description": "生成时间（可选，建议ISO时间格式）。"}}, "required": ["planId", "planVersion", "blueprintJson"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "save_plan_blueprint", "description": "保存全局规划蓝图（PlanBlueprint）到持久层，支持按 planId + planVersion 幂等写入。适用于大模型完成一次性全局规划后，将阶段划分、节点拓扑、资源提示与风险信息版本化落库。若同版本已存在则执行更新，不存在则执行插入。建议在规划阶段结束后立即调用，确保后续执行器按冻结版本推进。", "version": "1.0.0", "owner": "System", "beanName": "planBlueprintTools", "methodName": "savePlanBlueprint", "inputSchema": {"type": "object", "properties": {"planId": {"type": "string", "description": "计划ID（必填）。用于标识蓝图归属计划。"}, "planVersion": {"type": "integer", "description": "计划版本号（必填）。用于版本控制与回溯。"}, "blueprintJson": {"type": "string", "description": "蓝图JSON字符串（必填）。包含 phases/nodes/edges 等核心结构。"}, "generatedByModel": {"type": "string", "description": "生成模型标识（可选）。用于审计与效果分析。"}, "generatedAt": {"type": "string", "description": "生成时间（可选，建议ISO时间格式）。"}}, "required": ["planId", "planVersion", "blueprintJson"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'scan_dependency_vulnerabilities', 'scan_dependency_vulnerabilities', $json$执行依赖漏洞扫描（SCA），识别项目依赖中的已知安全风险并输出风险汇总。支持指定生态（maven/gradle/npm/pnpm/yarn/python/auto）与失败阈值（failOnSeverity），可用于发布前安全门禁。当前实现会按生态选择扫描命令并尝试汇总报告文件，返回漏洞分级统计与 thresholdReached 结果，便于上层做阻断、告警或自动修复决策。$json$, $json${"type": "object", "properties": {"repoPath": {"type": "string", "description": "仓库路径（必填）。用于检测生态并执行扫描命令。"}, "ecosystem": {"type": "string", "enum": ["maven", "gradle", "npm", "pnpm", "yarn", "python", "auto"], "description": "项目生态（可选）。传 auto 或不传时由系统自动识别。"}, "failOnSeverity": {"type": "string", "enum": ["CRITICAL", "HIGH", "MEDIUM", "LOW"], "description": "失败阈值（可选）。达到该级别及以上漏洞时返回错误状态。"}}, "required": ["repoPath"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.1.0', false, 'LOW', $json${"name": "scan_dependency_vulnerabilities", "description": "执行依赖漏洞扫描（SCA），识别项目依赖中的已知安全风险并输出风险汇总。支持指定生态（maven/gradle/npm/pnpm/yarn/python/auto）与失败阈值（failOnSeverity），可用于发布前安全门禁。当前实现会按生态选择扫描命令并尝试汇总报告文件，返回漏洞分级统计与 thresholdReached 结果，便于上层做阻断、告警或自动修复决策。", "version": "1.1.0", "owner": "System", "beanName": "codeOpsTools", "methodName": "scanDependencyVulnerabilities", "inputSchema": {"type": "object", "properties": {"repoPath": {"type": "string", "description": "仓库路径（必填）。用于检测生态并执行扫描命令。"}, "ecosystem": {"type": "string", "enum": ["maven", "gradle", "npm", "pnpm", "yarn", "python", "auto"], "description": "项目生态（可选）。传 auto 或不传时由系统自动识别。"}, "failOnSeverity": {"type": "string", "enum": ["CRITICAL", "HIGH", "MEDIUM", "LOW"], "description": "失败阈值（可选）。达到该级别及以上漏洞时返回错误状态。"}}, "required": ["repoPath"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'search_symbol_references', 'search_symbol_references', $json$按符号名扫描代码引用关系，辅助评估改动影响面与重构风险。适用于修改函数签名、删除字段、替换实现前的安全检查。当前实现提供基础文本检索能力，返回 file/line/snippet 结构化结果，可作为后续更精确语义索引（如 LSP/ctags）的降级路径。$json$, $json${"type": "object", "properties": {"repoPath": {"type": "string", "description": "仓库路径（必填）。用于限定搜索范围。"}, "symbol": {"type": "string", "description": "目标符号（必填）。可为类名、方法名、常量名等。"}, "language": {"type": "string", "description": "语言标识（可选）。用于上层筛选或后续扩展精准解析。"}}, "required": ["repoPath", "symbol"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "search_symbol_references", "description": "按符号名扫描代码引用关系，辅助评估改动影响面与重构风险。适用于修改函数签名、删除字段、替换实现前的安全检查。当前实现提供基础文本检索能力，返回 file/line/snippet 结构化结果，可作为后续更精确语义索引（如 LSP/ctags）的降级路径。", "version": "1.0.0", "owner": "System", "beanName": "codeOpsTools", "methodName": "searchSymbolReferences", "inputSchema": {"type": "object", "properties": {"repoPath": {"type": "string", "description": "仓库路径（必填）。用于限定搜索范围。"}, "symbol": {"type": "string", "description": "目标符号（必填）。可为类名、方法名、常量名等。"}, "language": {"type": "string", "description": "语言标识（可选）。用于上层筛选或后续扩展精准解析。"}}, "required": ["repoPath", "symbol"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'update_node_status', 'update_node_status', $json$更新计划节点状态与执行元数据。适用于调度器在节点开始、成功、失败、跳过等关键时机落盘状态，保障状态机一致性与可追溯性。支持附带耗时（costMs）、失败原因（failReason）、重试次数（retryCount）等字段，便于报表统计与失败重规划。建议仅由执行引擎调用，避免外部任意改写导致状态漂移。$json$, $json${"type": "object", "properties": {"planId": {"type": "string", "description": "计划ID（必填）。用于限定节点归属计划。"}, "nodeId": {"type": "string", "description": "节点ID（必填）。用于定位需要更新的节点。"}, "status": {"type": "string", "enum": ["PENDING", "RUNNING", "SUCCESS", "FAILED", "BLOCKED", "APPROVAL_PENDING", "SKIPPED"], "description": "目标状态（必填）。必须使用系统约定枚举值。"}, "costMs": {"type": "integer", "description": "执行耗时毫秒（可选）。通常在节点结束时回填。"}, "failReason": {"type": "string", "description": "失败原因（可选）。当状态为 FAILED 时建议提供。"}, "retryCount": {"type": "integer", "description": "当前重试次数（可选）。用于重试策略与审计分析。"}}, "required": ["planId", "nodeId", "status"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "update_node_status", "description": "更新计划节点状态与执行元数据。适用于调度器在节点开始、成功、失败、跳过等关键时机落盘状态，保障状态机一致性与可追溯性。支持附带耗时（costMs）、失败原因（failReason）、重试次数（retryCount）等字段，便于报表统计与失败重规划。建议仅由执行引擎调用，避免外部任意改写导致状态漂移。", "version": "1.0.0", "owner": "System", "beanName": "planNodeTools", "methodName": "updateNodeStatus", "inputSchema": {"type": "object", "properties": {"planId": {"type": "string", "description": "计划ID（必填）。用于限定节点归属计划。"}, "nodeId": {"type": "string", "description": "节点ID（必填）。用于定位需要更新的节点。"}, "status": {"type": "string", "enum": ["PENDING", "RUNNING", "SUCCESS", "FAILED", "BLOCKED", "APPROVAL_PENDING", "SKIPPED"], "description": "目标状态（必填）。必须使用系统约定枚举值。"}, "costMs": {"type": "integer", "description": "执行耗时毫秒（可选）。通常在节点结束时回填。"}, "failReason": {"type": "string", "description": "失败原因（可选）。当状态为 FAILED 时建议提供。"}, "retryCount": {"type": "integer", "description": "当前重试次数（可选）。用于重试策略与审计分析。"}}, "required": ["planId", "nodeId", "status"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'web_scrape', 'web_scrape', $json$抓取并提取指定网页的纯文本内容。当你通过搜索工具获得了一个 URL，且需要深入阅读该网页的详细内容以回答用户问题时，或者用户直接提供 URL 要求总结/提取信息时调用。$json$, $json${"type": "object", "properties": {"url": {"type": "string", "description": "目标网页 URL（必填）。需为可访问的完整链接（http/https）。"}}, "required": ["url"]}$json$::jsonb, $json${"type": "object", "properties": {"text": {"type": "string", "description": "网页正文提取结果（纯文本）。"}, "metadata": {"type": "object", "description": "网页元数据（如标题、来源、发布时间等，具体字段按返回结果为准）。"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "web_scrape", "description": "抓取并提取指定网页的纯文本内容。当你通过搜索工具获得了一个 URL，且需要深入阅读该网页的详细内容以回答用户问题时，或者用户直接提供 URL 要求总结/提取信息时调用。", "version": "1.0.0", "owner": "System", "beanName": "searchTools", "methodName": "web_scrape", "inputSchema": {"type": "object", "properties": {"url": {"type": "string", "description": "目标网页 URL（必填）。需为可访问的完整链接（http/https）。"}}, "required": ["url"]}, "outputSchema": {"type": "object", "properties": {"text": {"type": "string", "description": "网页正文提取结果（纯文本）。"}, "metadata": {"type": "object", "description": "网页元数据（如标题、来源、发布时间等，具体字段按返回结果为准）。"}}}}$json$::jsonb, NULL),
('local-agent-server', 'web_search', 'web_search', $json$执行通用互联网网页搜索。当你需要获取最新资讯、实时数据、或者你自身知识库中缺乏的外部事实时调用此工具。输入精准的搜索关键词，返回相关的网页链接和摘要片段。$json$, $json${"type": "object", "properties": {"query": {"type": "string", "description": "搜索关键词（必填）。建议提供明确主题与限定词，例如“广州今天天气 实时”。"}}, "required": ["query"]}$json$::jsonb, $json${"type": "object", "properties": {"organic": {"type": "array", "description": "网页搜索结果列表（通常包含标题、链接、摘要等字段）。"}, "peopleAlsoAsk": {"type": "array", "description": "相关问题列表（可能为空）。"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "web_search", "description": "执行通用互联网网页搜索。当你需要获取最新资讯、实时数据、或者你自身知识库中缺乏的外部事实时调用此工具。输入精准的搜索关键词，返回相关的网页链接和摘要片段。", "version": "1.0.0", "owner": "System", "beanName": "searchTools", "methodName": "web_search", "inputSchema": {"type": "object", "properties": {"query": {"type": "string", "description": "搜索关键词（必填）。建议提供明确主题与限定词，例如“广州今天天气 实时”。"}}, "required": ["query"]}, "outputSchema": {"type": "object", "properties": {"organic": {"type": "array", "description": "网页搜索结果列表（通常包含标题、链接、摘要等字段）。"}, "peopleAlsoAsk": {"type": "array", "description": "相关问题列表（可能为空）。"}}}}$json$::jsonb, NULL),
('local-agent-server', 'write_html_report_file', 'write_html_report_file', $json$将任务报告 HTML 内容写入本地文件并落库存档，返回 reportPath/reportUrl 供展示与追踪。适用于计划结束后的统一报告落地（成功、失败、部分成功均可）。支持自定义 fileName/outputDir，可选传 finalStatus/openResult 写入真实执行结果；未传时使用安全默认值。建议上层在调用前完成内容脱敏、路径规范化与敏感信息审查。$json$, $json${"type": "object", "properties": {"planId": {"type": "string", "description": "计划ID（必填）。用于命名与关联报告记录。"}, "htmlContent": {"type": "string", "description": "HTML 报告内容（必填）。建议包含阶段、节点、统计、错误摘要等信息。"}, "fileName": {"type": "string", "description": "报告文件名（可选）。不传时默认使用 {planId}.html。"}, "outputDir": {"type": "string", "description": "输出目录（可选）。不传时使用系统默认报告目录。"}, "finalStatus": {"type": "string", "enum": ["SUCCESS", "FAILED", "PARTIAL", "CANCELLED"], "description": "计划最终状态（可选）。用于报告记录与后续统计。"}, "openResult": {"type": "string", "enum": ["SUCCESS", "FAILED", "NOT_SUPPORTED"], "description": "报告打开结果（可选）。用于记录展示环节执行情况。"}}, "required": ["planId", "htmlContent"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.1.0', false, 'LOW', $json${"name": "write_html_report_file", "description": "将任务报告 HTML 内容写入本地文件并落库存档，返回 reportPath/reportUrl 供展示与追踪。适用于计划结束后的统一报告落地（成功、失败、部分成功均可）。支持自定义 fileName/outputDir，可选传 finalStatus/openResult 写入真实执行结果；未传时使用安全默认值。建议上层在调用前完成内容脱敏、路径规范化与敏感信息审查。", "version": "1.1.0", "owner": "System", "beanName": "planReportTools", "methodName": "writeHtmlReportFile", "inputSchema": {"type": "object", "properties": {"planId": {"type": "string", "description": "计划ID（必填）。用于命名与关联报告记录。"}, "htmlContent": {"type": "string", "description": "HTML 报告内容（必填）。建议包含阶段、节点、统计、错误摘要等信息。"}, "fileName": {"type": "string", "description": "报告文件名（可选）。不传时默认使用 {planId}.html。"}, "outputDir": {"type": "string", "description": "输出目录（可选）。不传时使用系统默认报告目录。"}, "finalStatus": {"type": "string", "enum": ["SUCCESS", "FAILED", "PARTIAL", "CANCELLED"], "description": "计划最终状态（可选）。用于报告记录与后续统计。"}, "openResult": {"type": "string", "enum": ["SUCCESS", "FAILED", "NOT_SUPPORTED"], "description": "报告打开结果（可选）。用于记录展示环节执行情况。"}}, "required": ["planId", "htmlContent"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL),
('local-agent-server', 'write_source_file', 'write_source_file', $json$写入源码文件内容，支持可选备份原文件。适用于生成代码、落地修复结果、更新测试文件等场景。为降低风险，建议在高风险改动前设置 backup=true，并确保 filePath 位于受控仓库目录内，避免路径越界写入。该工具适合与 git_create_checkpoint、apply_unified_patch 联合使用，形成可回滚改动链路。$json$, $json${"type": "object", "properties": {"filePath": {"type": "string", "description": "目标文件路径（必填）。若目录不存在会自动创建父目录。"}, "content": {"type": "string", "description": "写入内容（必填）。将以 UTF-8 覆盖写入。"}, "backup": {"type": "boolean", "description": "是否先备份原文件（可选）。true 时会生成带时间戳的 .bak 文件。"}}, "required": ["filePath", "content"]}$json$::jsonb, $json${"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}$json$::jsonb, NULL, '[]'::jsonb, true, '1.0.0', false, 'LOW', $json${"name": "write_source_file", "description": "写入源码文件内容，支持可选备份原文件。适用于生成代码、落地修复结果、更新测试文件等场景。为降低风险，建议在高风险改动前设置 backup=true，并确保 filePath 位于受控仓库目录内，避免路径越界写入。该工具适合与 git_create_checkpoint、apply_unified_patch 联合使用，形成可回滚改动链路。", "version": "1.0.0", "owner": "System", "beanName": "codeOpsTools", "methodName": "writeSourceFile", "inputSchema": {"type": "object", "properties": {"filePath": {"type": "string", "description": "目标文件路径（必填）。若目录不存在会自动创建父目录。"}, "content": {"type": "string", "description": "写入内容（必填）。将以 UTF-8 覆盖写入。"}, "backup": {"type": "boolean", "description": "是否先备份原文件（可选）。true 时会生成带时间戳的 .bak 文件。"}}, "required": ["filePath", "content"]}, "outputSchema": {"type": "object", "properties": {"status": {"type": "string"}, "data": {"type": "object"}}}}$json$::jsonb, NULL)
